  "severity": "minor",
  "text": "The posts are thin and generic: about 4 short paragraphs each, with invented anonymous quotes (/why-mcp-is-awesome-part-1/, /why-mcp-is-awesome-part-2/)"
 },
 {
  "severity": "minor",
  "text": "The \"prose\" class does nothing without @tailwindcss/typography, so rich-text paragraphs have no spacing (Views/Shared/Components/RichText/Default.cshtml)"
 },
 {
  "severity": "minor",
  "text": "There is no site header, nav or footer, and the front page body is a single placeholder sentence (Views/blogFrontPage.cshtml)"
 },
 {
  "severity": "minor",
  "text": "Both templates repeat the full HTML shell with Layout = null, and the Back link is hard-coded to \"/\" (Views/blogPost.cshtml)"
 }
]
